import keepAwakeMessages from "./keep-awake-i18n.json";
import type { DesktopErrorCode } from "./api";

export const APP_LOCALES = [
  "en",
  "zh-CN",
  "hi",
  "es",
  "ar",
  "fr",
  "bn",
  "pt",
  "id",
  "ur",
] as const;

export type AppLocale = (typeof APP_LOCALES)[number];

export const APP_LOCALE_OPTIONS: ReadonlyArray<{
  code: AppLocale;
  label: string;
  direction: "ltr" | "rtl";
}> = [
  { code: "en", label: "English", direction: "ltr" },
  { code: "zh-CN", label: "简体中文", direction: "ltr" },
  { code: "hi", label: "हिन्दी", direction: "ltr" },
  { code: "es", label: "Español", direction: "ltr" },
  { code: "ar", label: "العربية", direction: "rtl" },
  { code: "fr", label: "Français", direction: "ltr" },
  { code: "bn", label: "বাংলা", direction: "ltr" },
  { code: "pt", label: "Português", direction: "ltr" },
  { code: "id", label: "Bahasa Indonesia", direction: "ltr" },
  { code: "ur", label: "اردو", direction: "rtl" },
];

const APP_LOCALE_SET = new Set<string>(APP_LOCALES);

export function isAppLocale(value: unknown): value is AppLocale {
  return typeof value === "string" && APP_LOCALE_SET.has(value);
}

export function appLocaleDirection(locale: AppLocale): "ltr" | "rtl" {
  return locale === "ar" || locale === "ur" ? "rtl" : "ltr";
}

export const LOCALE_STORAGE_KEY = "relayune.locale";

export function persistAppLocale(
  locale: AppLocale,
  getStorage: () => Pick<Storage, "setItem"> = () => window.localStorage,
) {
  try {
    getStorage().setItem(LOCALE_STORAGE_KEY, locale);
  } catch {
    // Native config is authoritative. Restricted WebView storage must not
    // roll the window back after the native menu language already changed.
  }
}

export function bootstrapLocaleAfterRefresh(
  persistedLocale: unknown,
  currentLocale: AppLocale,
  context: {
    switchRevisionAtStart: number;
    currentSwitchRevision: number;
    switchWasIdleAtStart: boolean;
    switchInFlight: boolean;
  },
): AppLocale {
  const nativeLocale = isAppLocale(persistedLocale) ? persistedLocale : null;
  const refreshDidNotOverlapLanguageChange =
    context.switchWasIdleAtStart &&
    !context.switchInFlight &&
    context.switchRevisionAtStart === context.currentSwitchRevision;
  return nativeLocale && refreshDidNotOverlapLanguageChange
    ? nativeLocale
    : currentLocale;
}

