function localeFromLanguageTag(language: string): AppLocale | null {
  const normalized = language.trim().replaceAll("_", "-").toLowerCase();
  if (!normalized) return null;
  if (
    normalized === "zh" ||
    normalized === "zh-cn" ||
    normalized === "zh-hans" ||
    normalized.startsWith("zh-hans-")
  ) {
    return "zh-CN";
  }
  if (normalized.startsWith("zh-")) return null;
  const base = normalized.split("-")[0];
  return isAppLocale(base) ? base : null;
}

export function detectAppLocale(
  languages: readonly string[],
  storedLocale?: string | null,
): AppLocale {
  if (isAppLocale(storedLocale)) return storedLocale;
  for (const language of languages) {
    const locale = localeFromLanguageTag(language);
    if (locale) return locale;
  }
  return "en";
}

export function translate(
  locale: AppLocale,
  key: TranslationKey,
  params: TranslationParams = {},
): string {
  const template = locale === "zh-CN" || locale === "en"
    ? baseMessages[locale][key]
    : additionalMessages[locale][key] ?? baseMessages.en[key];
  return template.replace(/\{(\w+)\}/g, (placeholder, name) => {
    if (!(name in params)) return placeholder;
    const value = params[name];
    return typeof value === "number"
      ? new Intl.NumberFormat(locale).format(value)
      : String(value);
  });
}

export function translationCoverage(locale: AppLocale) {
  const total = Object.keys(baseMessages.en).length;
  const translated = locale === "zh-CN" || locale === "en"
    ? total
    : Object.keys(additionalMessages[locale]).length;
  return { translated, fallback: total - translated, total };
}

export function hasDirectTranslation(
  locale: AppLocale,
  key: TranslationKey,
): boolean {
  return locale === "zh-CN" || locale === "en" ||
    Object.hasOwn(additionalMessages[locale], key);
}

export function localizedUpdateNotes(
  locale: AppLocale,
  notes?: string | null,
): string | null {
  const value = notes?.trim();
  if (!value) return null;
  try {
    const localized = JSON.parse(value) as Record<string, unknown>;
    const selected = localized?.[locale] ??
      (locale === "zh-CN" ? localized?.zh : undefined) ??
      localized?.en;
    return typeof selected === "string" && selected.trim()
      ? selected.trim()
      : null;
  } catch {
    // Older manifests used one plain-language string. Only reuse it when its
    // script matches the active UI; otherwise prefer the stable local copy.
  }
  if (locale !== "en" && locale !== "zh-CN") return null;
  const containsHan = /[\u3400-\u9fff]/u.test(value);
  if ((locale === "en" && containsHan) || (locale === "zh-CN" && !containsHan)) {
    return null;
  }
  return value;
}

const desktopErrorTranslationKeys: Record<DesktopErrorCode, TranslationKey> = {
  keep_awake_failed: "keepAwakeError",
  startup_failed: "startupFailed",
  settings_invalid: "settingsInvalidError",
  instance_probe_failed: "secureConnectionFailed",
  instance_cleanup_failed: "credentialAccessError",
  server_url_invalid: "serverUrlInvalidError",
  server_https_required: "serverHttpsError",
  server_credentials_forbidden: "serverCredentialsError",
  server_components_forbidden: "serverComponentsError",
  workspace_invalid: "workspaceInvalidError",
  codex_path_invalid: "codexPathInvalidError",
  kimi_path_invalid: "kimiPathInvalidError",
  claude_path_invalid: "claudePathInvalidError",
  agent_check_failed: "agentCheckError",
  agent_install_failed: "agentInstallError",
  agent_login_failed: "agentLoginError",
  settings_save_failed: "settingsSaveError",
  relay_credentials_missing: "relayCredentialsError",
  relay_unauthorized: "relayUnauthorizedError",
  relay_reconnecting: "relayReconnectingError",
  relay_legacy_process: "legacyRelayError",
  relay_start_failed: "relayStartError",
  relay_stop_failed: "relayStopError",
  relay_exited: "relayExitedError",
  sign_in_failed: "signInError",
  sign_out_failed: "signOutError",
  credential_access_failed: "credentialAccessError",
  autostart_failed: "autostartError",
  workspace_picker_failed: "workspacePickerError",
  open_web_failed: "openWebError",
  pairing_failed: "pairingNativeError",
  browser_access_failed: "browserAccessError",
  language_failed: "languageError",
  window_failed: "windowError",
  update_failed: "updateFailed",
  unknown: "desktopUnknownError",
};

export function desktopErrorMessage(
  locale: AppLocale,
  code: DesktopErrorCode,
): string {
  return translate(locale, desktopErrorTranslationKeys[code]);
}
